package main

import (
	"os"
	"os/exec"
)

func executeCommand(name string, args []string) error {
	cmd := exec.Command(name, args...)
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	return cmd.Run()
}

package main

import (
	"os"
	"os/exec"
)

func runAndWait(name string, args []string) error {
	cmd := exec.Command(name, args...)
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	err := cmd.Start()
	if err != nil {
		return err
	}
	return cmd.Wait()
}

package main

import (
	"errors"
	"fmt"
	"os"
	"os/exec"
)

func safeExecute(name string, args []string) {
	cmd := exec.Command(name, args...)
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	err := cmd.Run()
	if err != nil {
		if errors.Is(err, exec.ErrNotFound) {
			fmt.Fprintf(os.Stderr, "shell: command not found: %s\n", name)
		} else {
			fmt.Fprintf(os.Stderr, "shell: error executing %s: %v\n", name, err)
		}
	}
}
